function villageTiming(){
 const n=nurseryTiming(),start=Math.max(n.end,Number(fx.villageStart)||0),duration=k=>Math.max(.1,Number(fx[k])||.1);
 const boysAt=duration('villageWindowTime'),boysExitAt=boysAt+duration('villageBoysHold'),townAt=boysExitAt+duration('villageBoysExitTime'),craftAt=townAt+duration('villageTownHold'),craftHoldAt=craftAt+duration('villageCraftWipeTime'),clothAt=craftHoldAt+duration('villageCraftHold'),seamstressAt=clothAt+duration('villageClothWipeTime'),exitAt=seamstressAt+duration('villageSeamstressHold');
 return {start,boysAt,boysExitAt,townAt,craftAt,craftHoldAt,clothAt,seamstressAt,exitAt,end:start+exitAt+Math.max(0,Number(fx.villageFadeTime)||0)};
}
