function repaintVillage(){base._renderKey='';frame(base,t);const note=document.querySelector('#villageAssetStatus');if(note)note.textContent=Object.keys(villageSources).filter(k=>sprites[k]?.naturalWidth).length+' / 4 continuation images ready'+(Object.keys(villageSources).some(k=>sprites[k]?._loadError)?' · image unavailable':'')}
function loadVillageAssets(restore=true){for(const [key,src] of Object.entries(villageSources)){sources[key]=src;const im=new Image();im.onload=()=>{im._loadError='';repaintVillage()};im.onerror=()=>{im._loadError=src;repaintVillage()};sprites[key]=im;im.src=src}if(restore)restoreAssets()}
loadVillageAssets();
async function resetVillageAssets(){try{const db=await assetDB(),tx=db.transaction('assets','readwrite');for(const key of Object.keys(villageSources))tx.objectStore('assets').delete(key);await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();loadVillageAssets(false)}catch{const note=document.querySelector('#villageAssetStatus');if(note)note.textContent='Could not reset local images. Your replacements are retained.'}}
