const renderBeforeVillage=renderDepotControls;renderDepotControls=function(){renderBeforeVillage();const host=document.querySelector('#depotControls');if(!host)return;const v=villageTiming(),watch=age=>{seekDepot(age);playing=true;document.querySelector('#play').textContent='Ⅱ'};
 const quick=document.createElement('div');quick.className='contextActions';host.prepend(quick);toolButton(quick,'Watch boys → town → crafts',()=>watch(v.start-.3));toolButton(quick,'Watch workshop → blouse',()=>watch(v.start+v.craftAt-.3));
 const jump=host.querySelector('select[aria-label="Jump to scene moment"]');for(const [label,age]of [['Window approach',v.start+fx.villageWindowTime*.5],['Rudi & Adi',v.start+v.boysAt+.5],['Boys exit',v.start+v.boysExitAt+fx.villageBoysExitTime*.5],['Herzogenaurach',v.start+v.townAt+.5],['Workshop passage',v.start+v.craftAt+fx.villageCraftWipeTime*.5],['Shoemaker',v.start+v.craftHoldAt+1],['Blouse passage',v.start+v.clothAt+fx.villageClothWipeTime*.5],['Woman & blouse',v.start+v.seamstressAt+1]])jump?.add(new Option(label,age));
 const section=document.createElement('details');section.className='directorSection';section.innerHTML='<summary>Boys, town & crafts</summary><p class="sub">Continue through the window to Rudi and Adi, the town square, shoemaking and the blouse. Fine-tune or keyframe surfaces under Look & motion.</p>';host.append(section);
 toolField(section,'Left boy name',fx,'villageLeftName','text');toolField(section,'Right boy name',fx,'villageRightName','text');toolField(section,'Town title',fx,'villageTownTitle','text');toolNumbers(section,fx,[['villageWindowTime','Window approach duration',.2,15,.1],['villageBoysHold','Boys hold',.1,30,.1],['villageTownHold','Town hold',.1,30,.1],['villageCraftHold','Shoemaker hold',.1,30,.1],['villageSeamstressHold','Blouse hold',.1,30,.1]]);
 toolButton(section,'Reference passage',()=>{Object.assign(fx,{villageTransition:'occlude',villageEase:'smooth',villagePassBlur:4,villageEdgeLight:.08});assetSave();renderDepotControls()});toolButton(section,'Soft passage',()=>{Object.assign(fx,{villageTransition:'dissolve',villageEase:'smooth',villageEdgeLight:0});assetSave();renderDepotControls()});toolButton(section,fx.villageEnabled?'Disable continuation':'Enable continuation',()=>{fx.villageEnabled=!fx.villageEnabled;assetSave();renderDepotControls()});
 const assets=document.createElement('details');assets.className='directorSection';assets.innerHTML='<summary>Continuation images · advanced</summary>';section.append(assets);for(const [key,label]of [['villageBoys','Replace boys…'],['villageTown','Replace town…'],['villageWorkshop','Replace workshop…'],['villageSeamstress','Replace blouse room…']])toolButton(assets,label,()=>chooseAsset(key));toolButton(assets,'Retry images',()=>loadVillageAssets());toolButton(assets,'Restore bundled continuation images',resetVillageAssets);const note=document.createElement('p');note.id='villageAssetStatus';note.className='sub';note.textContent=Object.keys(villageSources).filter(k=>sprites[k]?.naturalWidth).length+' / 4 continuation images ready';assets.append(note);
 const surface=host.querySelector('#depotSurface');surface?.addEventListener('change',()=>{if(!surface.value.startsWith('village'))return;const preview=[...host.querySelectorAll('button')].find(b=>b.textContent==='Preview this surface');if(preview)preview.onclick=()=>{const at={villageTiming:0,villageWindow:0,villageBoys:v.boysAt,villageTown:v.townAt,villageWorkshop:v.craftAt,villageSeamstress:v.clothAt,villagePasser:v.craftAt}[surface.value]||0;watch(v.start+at)}});
};
